-- ITR Intake: Postgres schema for Supabase (translated from the SQLite
-- migrations 0001-0006 in backend/itr_intake_server/migrations).
--
-- How to apply: Supabase dashboard -> SQL Editor -> New query -> paste this
-- whole file -> Run. It is safe to run once on an empty project; running it
-- again stops at the version check without changing anything. Then apply each
-- file in supabase/migrations in order (0002_..., ...) the same way.
--
-- Conventions
--   * IDs are UUIDs generated by the application (gen_random_uuid() is only a
--     default for convenience).
--   * Timestamps are timestamptz (UTC). Money is numeric, never float.
--   * Ownership: every case-scoped row carries firm_id and references
--     cases (id, firm_id), so a row can never belong to one case but another
--     firm. Sessions, cases and firm-code usage reference (id, firm_id) pairs.
--   * Children of a case are deleted with it; firms, users and audit history
--     are never deleted implicitly.
--   * Security: the app connects with the database owner role over
--     DATABASE_URL (server only). Row Level Security is enabled on every table
--     with no policies, and the anon/authenticated roles get no privileges,
--     so Supabase's public Data API exposes nothing.

BEGIN;

CREATE TABLE IF NOT EXISTS schema_migrations (
    version    integer PRIMARY KEY,
    name       text NOT NULL,
    applied_at timestamptz NOT NULL DEFAULT now()
);

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM schema_migrations WHERE version = 1) THEN
        RAISE EXCEPTION 'ITR Intake schema version 1 is already applied; nothing to do.';
    END IF;
END $$;

-- Shared helpers -------------------------------------------------------------------

CREATE FUNCTION itr_reject_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
END $$;

-- Firms ---------------------------------------------------------------------------

CREATE TABLE firms (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name                text NOT NULL CHECK (length(trim(name)) > 0),
    contact_phone       text,
    contact_address     text,
    registration_number text CHECK (registration_number IS NULL OR length(trim(registration_number)) > 0),
    status              text NOT NULL DEFAULT 'pending_verification'
                        CHECK (status IN ('pending_verification', 'pending_approval', 'active', 'suspended')),
    approved_at         timestamptz,
    approved_by         text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    CHECK (status <> 'active' OR approved_at IS NOT NULL)
);

-- Professional details are self-declared and unverified; a duplicate
-- registration number is refused outright.
CREATE UNIQUE INDEX firms_registration_number_uq ON firms (registration_number) WHERE registration_number IS NOT NULL;

-- CA users ------------------------------------------------------------------------

CREATE TABLE ca_users (
    id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    firm_id           uuid NOT NULL REFERENCES firms (id),
    email_norm        text NOT NULL UNIQUE CHECK (email_norm = lower(trim(email_norm)) AND email_norm LIKE '%_@_%'),
    full_name         text NOT NULL CHECK (length(trim(full_name)) > 0),
    password_hash     text NOT NULL CHECK (length(password_hash) > 0),
    email_verified_at timestamptz,
    status            text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'disabled')),
    role              text NOT NULL DEFAULT 'owner' CHECK (role IN ('owner', 'member')),
    failed_logins     integer NOT NULL DEFAULT 0 CHECK (failed_logins >= 0),
    locked_until      timestamptz,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, firm_id)
);

CREATE INDEX ca_users_firm_idx ON ca_users (firm_id);

-- Firm codes ----------------------------------------------------------------------
-- A firm code identifies a firm to new clients; it never authenticates anyone.

CREATE TABLE firm_codes (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    firm_id    uuid NOT NULL REFERENCES firms (id),
    code       text NOT NULL UNIQUE CHECK (code ~ '^[0-9A-Z]{8,32}$'),
    status     text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
    created_at timestamptz NOT NULL DEFAULT now(),
    revoked_at timestamptz,
    CHECK ((status = 'revoked') = (revoked_at IS NOT NULL)),
    UNIQUE (id, firm_id)
);

-- At most one active code per firm.
CREATE UNIQUE INDEX firm_codes_one_active_uq ON firm_codes (firm_id) WHERE status = 'active';

-- Client identities ---------------------------------------------------------------
-- Scoped to one firm: the same e-mail at two firms is two unrelated identities.

CREATE TABLE client_identities (
    id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    firm_id           uuid NOT NULL REFERENCES firms (id),
    email_norm        text NOT NULL CHECK (email_norm = lower(trim(email_norm)) AND email_norm LIKE '%_@_%'),
    email_verified_at timestamptz,
    created_at        timestamptz NOT NULL DEFAULT now(),
    UNIQUE (firm_id, email_norm),
    UNIQUE (id, firm_id)
);

-- Verification challenges ---------------------------------------------------------
-- One-time tokens. Only a SHA-256 hash of the secret is stored. A client
-- challenge records the firm code the client entered, which must belong to the
-- same firm (composite foreign key).

CREATE TABLE verification_challenges (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    purpose      text NOT NULL CHECK (purpose IN ('client_login', 'ca_email_verification', 'ca_password_reset')),
    firm_id      uuid REFERENCES firms (id),
    ca_user_id   uuid REFERENCES ca_users (id) ON DELETE CASCADE,
    firm_code_id uuid,
    subject      text NOT NULL CHECK (length(subject) > 0),
    secret_hash  text NOT NULL CHECK (secret_hash ~ '^[0-9a-f]{64}$'),
    attempts     integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts integer NOT NULL CHECK (max_attempts > 0),
    expires_at   timestamptz NOT NULL,
    consumed_at  timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    CHECK (attempts <= max_attempts),
    CHECK (purpose <> 'client_login' OR (firm_id IS NOT NULL AND ca_user_id IS NULL)),
    CHECK (purpose = 'client_login' OR ca_user_id IS NOT NULL),
    CHECK (firm_code_id IS NULL OR purpose = 'client_login'),
    FOREIGN KEY (firm_code_id, firm_id) REFERENCES firm_codes (id, firm_id)
);

CREATE INDEX verification_challenges_lookup_idx ON verification_challenges (purpose, subject, created_at);
CREATE INDEX verification_challenges_client_idx
    ON verification_challenges (purpose, firm_id, subject) WHERE purpose = 'client_login';

-- Sessions ------------------------------------------------------------------------
-- Server-side sessions; only a SHA-256 hash of the token is stored.

CREATE TABLE sessions (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    token_hash          text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    kind                text NOT NULL CHECK (kind IN ('ca', 'client')),
    firm_id             uuid NOT NULL REFERENCES firms (id),
    ca_user_id          uuid,
    client_identity_id  uuid,
    firm_code_id        uuid,
    created_at          timestamptz NOT NULL DEFAULT now(),
    last_seen_at        timestamptz NOT NULL DEFAULT now(),
    idle_expires_at     timestamptz NOT NULL,
    absolute_expires_at timestamptz NOT NULL,
    revoked_at          timestamptz,
    CHECK ((kind = 'ca' AND ca_user_id IS NOT NULL AND client_identity_id IS NULL)
        OR (kind = 'client' AND client_identity_id IS NOT NULL AND ca_user_id IS NULL)),
    CHECK (firm_code_id IS NULL OR kind = 'client'),
    -- The session's firm must be the user's (and the firm code's) firm.
    FOREIGN KEY (ca_user_id, firm_id) REFERENCES ca_users (id, firm_id) ON DELETE CASCADE,
    FOREIGN KEY (client_identity_id, firm_id) REFERENCES client_identities (id, firm_id) ON DELETE CASCADE,
    FOREIGN KEY (firm_code_id, firm_id) REFERENCES firm_codes (id, firm_id)
);

CREATE INDEX sessions_expiry_idx ON sessions (absolute_expires_at);

-- Rate limits ---------------------------------------------------------------------
-- Fixed-window counters. Buckets hold hashes, never raw addresses or e-mails.

CREATE TABLE rate_limits (
    bucket       text NOT NULL CHECK (length(bucket) > 0),
    window_start timestamptz NOT NULL,
    count        integer NOT NULL CHECK (count >= 0),
    PRIMARY KEY (bucket, window_start)
);

-- Cases ---------------------------------------------------------------------------

CREATE TABLE cases (
    id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    firm_id                  uuid NOT NULL REFERENCES firms (id),
    client_identity_id       uuid NOT NULL,
    reference                text NOT NULL UNIQUE CHECK (reference ~ '^IT-[0-9A-Z-]+$'),
    financial_year           text NOT NULL CHECK (financial_year ~ '^[0-9]{4}-[0-9]{2}$'),
    client_first_name        text NOT NULL CHECK (length(trim(client_first_name)) > 0),
    profile_json             jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(profile_json) = 'object'),
    status                   text NOT NULL DEFAULT 'draft'
                             CHECK (status IN ('draft', 'statement_uploaded', 'processing', 'questions_in_progress',
                                               'documents_pending', 'submitted', 'ca_review_required',
                                               'review_ready', 'closed')),
    created_via_firm_code_id uuid,
    opening_balance          numeric(18, 2),
    closing_balance          numeric(18, 2),
    period_start             date,
    period_end               date,
    classifier_version       text,
    stopped_reason           text CHECK (stopped_reason IS NULL OR stopped_reason IN
                                         ('turn_cap_reached', 'model_no_further_question', 'nothing_left_to_ask')),
    questions_issued         integer NOT NULL DEFAULT 0 CHECK (questions_issued >= 0),
    version                  integer NOT NULL DEFAULT 1 CHECK (version >= 1),
    generation_lease_until   timestamptz,
    reviewed_upload_id       uuid,  -- foreign key added after statement_uploads exists
    reviewed_at              timestamptz,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    closed_at                timestamptz,
    CHECK ((status = 'closed') = (closed_at IS NOT NULL)),
    UNIQUE (id, firm_id),
    -- The client identity and the firm code used must belong to the case's firm.
    FOREIGN KEY (client_identity_id, firm_id) REFERENCES client_identities (id, firm_id),
    FOREIGN KEY (created_via_firm_code_id, firm_id) REFERENCES firm_codes (id, firm_id)
);

-- One open case per client identity, firm and financial year.
CREATE UNIQUE INDEX cases_one_open_per_client_year_uq
    ON cases (firm_id, client_identity_id, financial_year) WHERE status <> 'closed';
CREATE INDEX cases_firm_status_idx ON cases (firm_id, status, updated_at);
CREATE INDEX cases_client_idx ON cases (client_identity_id);

-- Statement rows ------------------------------------------------------------------
-- The extracted rows (raw text kept exactly) and the classifier's result.

CREATE TABLE statement_rows (
    case_id               uuid NOT NULL,
    firm_id               uuid NOT NULL,
    row_number            integer NOT NULL CHECK (row_number > 0),
    raw_date              text,
    raw_narration         text,
    raw_debit             text,
    raw_credit            text,
    raw_balance           text,
    is_valid              boolean NOT NULL,
    issues_json           jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(issues_json) = 'array'),
    txn_date              date,
    narration             text,
    debit                 numeric(18, 2) CHECK (debit IS NULL OR debit >= 0),
    credit                numeric(18, 2) CHECK (credit IS NULL OR credit >= 0),
    balance               numeric(18, 2),
    mode                  text,
    counterparty          text,
    category              text CHECK (category IS NULL OR category IN (
                              'Salary / Pension', 'Business / Professional Receipts', 'Rent Received',
                              'Interest – Savings Bank', 'Interest – FD / RD / Others', 'Dividend',
                              'Sale / Redemption of Investments', 'Income Tax Refund',
                              'Loans Received / Repayment of Loans Given', 'Gifts / Receipts from Non-relatives',
                              'Investments – Tax-saving', 'Investments – Others', 'Insurance – Health',
                              'Loan EMI / Repayment', 'Loans Given', 'Tax Payments', 'Donations',
                              'Credit Card Payments', 'Rent Paid', 'Business / Professional Expenses',
                              'Self Transfer', 'Family Transfer', 'Cash Withdrawal', 'Cash Deposit',
                              'Personal Expenses', 'Bank Charges', 'Reversals / Refunds', 'Others – Needs Review')),
    confidence            text CHECK (confidence IS NULL OR confidence IN ('high', 'medium', 'low')),
    review_status         text CHECK (review_status IS NULL OR review_status IN
                                      ('Auto-classified', 'Needs confirmation', 'Needs review')),
    matched_rule          text,
    flags_json            jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(flags_json) = 'array'),
    classification_reason text,
    classifier_version    text,
    -- A valid row has its parsed facts; an invalid row has no classification.
    CHECK (NOT is_valid OR (txn_date IS NOT NULL AND narration IS NOT NULL AND debit IS NOT NULL AND credit IS NOT NULL)),
    CHECK (is_valid OR (category IS NULL AND matched_rule IS NULL)),
    PRIMARY KEY (case_id, row_number),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE
);

-- Questions and confirmations (intake workflow; not yet used by the website) ---

CREATE TABLE questions (
    case_id                 uuid NOT NULL,
    firm_id                 uuid NOT NULL,
    question_id             text NOT NULL CHECK (question_id LIKE 'Q-%'),
    seq                     integer NOT NULL CHECK (seq > 0),
    question                text NOT NULL CHECK (length(trim(question)) > 0),
    purpose                 text NOT NULL CHECK (length(trim(purpose)) > 0),
    finding_ids_json        jsonb NOT NULL CHECK (jsonb_typeof(finding_ids_json) = 'array'
                                                  AND jsonb_array_length(finding_ids_json) > 0),
    transaction_ids_json    jsonb NOT NULL CHECK (jsonb_typeof(transaction_ids_json) = 'array'
                                                  AND jsonb_array_length(transaction_ids_json) > 0),
    presentation_fixes_json jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(presentation_fixes_json) = 'array'),
    status                  text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'answered', 'withdrawn')),
    answer_text             text CHECK (answer_text IS NULL OR length(trim(answer_text)) > 0),
    answered_at             timestamptz,
    created_at              timestamptz NOT NULL DEFAULT now(),
    CHECK ((status = 'answered') = (answer_text IS NOT NULL AND answered_at IS NOT NULL)),
    PRIMARY KEY (case_id, question_id),
    UNIQUE (case_id, seq),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX questions_one_pending_uq ON questions (case_id) WHERE status = 'pending';

CREATE TABLE confirmations (
    case_id           uuid NOT NULL,
    firm_id           uuid NOT NULL,
    seq               integer NOT NULL CHECK (seq > 0),
    finding_id        text NOT NULL CHECK (finding_id ~ '^F[0-9]'),
    proposed_category text NOT NULL,
    response          text NOT NULL CHECK (response IN ('confirmed', 'denied', 'unsure')),
    created_at        timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (case_id, seq),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE
);

CREATE TRIGGER confirmations_append_only BEFORE UPDATE ON confirmations
    FOR EACH ROW EXECUTE FUNCTION itr_reject_change();

-- Document requests and documents --------------------------------------------------

CREATE TABLE document_requests (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    case_id     uuid NOT NULL,
    firm_id     uuid NOT NULL,
    key         text NOT NULL CHECK (key ~ '^[a-z0-9_]+$'),
    label       text NOT NULL CHECK (length(trim(label)) > 0),
    description text CHECK (description IS NULL OR length(description) <= 500),
    required    boolean NOT NULL DEFAULT true,
    status      text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'received', 'waived')),
    source      text NOT NULL CHECK (source IN ('rules', 'ca')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (case_id, key),
    UNIQUE (id, case_id),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE
);

CREATE TABLE documents (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    case_id      uuid NOT NULL,
    firm_id      uuid NOT NULL,
    request_id   uuid,
    kind         text NOT NULL CHECK (kind IN ('bank_statement', 'supporting', 'workbook')),
    -- Object path in the private storage bucket, generated by the server and
    -- confined to this firm's and case's folder: "<firm>/<case>/<document>.<ext>".
    storage_key  text NOT NULL UNIQUE
                 CHECK (left(storage_key, 74) = firm_id::text || '/' || case_id::text || '/'
                        AND length(storage_key) > 74
                        AND position('..' IN storage_key) = 0 AND position('\' IN storage_key) = 0
                        AND position(':' IN storage_key) = 0 AND position('/' IN substr(storage_key, 75)) = 0),
    display_name text NOT NULL CHECK (length(trim(display_name)) > 0),
    content_type text NOT NULL CHECK (length(content_type) > 0),
    size_bytes   integer NOT NULL CHECK (size_bytes > 0),
    sha256       text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    status       text NOT NULL DEFAULT 'stored' CHECK (status IN ('stored', 'rejected', 'superseded')),
    uploaded_by  text NOT NULL CHECK (uploaded_by IN ('client', 'ca', 'system')),
    created_at   timestamptz NOT NULL DEFAULT now(),
    CHECK (kind <> 'workbook' OR uploaded_by = 'system'),
    CHECK (kind = 'supporting' OR request_id IS NULL),
    UNIQUE (case_id, kind, sha256),
    UNIQUE (id, case_id, firm_id),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE,
    -- A document can only fulfil a request of its own case.
    FOREIGN KEY (request_id, case_id) REFERENCES document_requests (id, case_id)
);

CREATE INDEX documents_case_kind_idx ON documents (case_id, kind);

-- Statement uploads -----------------------------------------------------------------
-- Each upload attempt, stored or not, with its processing outcome. Only counts,
-- codes, row numbers and page numbers: never transaction text or amounts.

CREATE TABLE statement_uploads (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    case_id             uuid NOT NULL,
    firm_id             uuid NOT NULL,
    document_id         uuid UNIQUE,
    file_type           text NOT NULL CHECK (file_type IN ('pdf', 'csv', 'unknown')),
    display_name        text NOT NULL CHECK (length(display_name) BETWEEN 1 AND 120),
    size_bytes          integer NOT NULL CHECK (size_bytes >= 0),
    status              text NOT NULL CHECK (status IN ('processing', 'extracted', 'manual_review_required',
                                                        'rejected', 'processing_failed')),
    reasons_json        jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(reasons_json) = 'array'),
    page_warnings_json  jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(page_warnings_json) = 'array'),
    rejected_rows_json  jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(rejected_rows_json) = 'array'),
    duplicate_rows_json jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(duplicate_rows_json) = 'array'),
    pages_total         integer CHECK (pages_total IS NULL OR pages_total >= 0),
    rows_extracted      integer NOT NULL DEFAULT 0 CHECK (rows_extracted >= 0),
    rows_rejected       integer NOT NULL DEFAULT 0 CHECK (rows_rejected >= 0),
    rows_duplicate      integer NOT NULL DEFAULT 0 CHECK (rows_duplicate >= 0),
    rows_summary        integer NOT NULL DEFAULT 0 CHECK (rows_summary >= 0),
    period_start        date,
    period_end          date,
    error_code          text CHECK (error_code IS NULL OR error_code ~ '^[a-z0-9_]{1,64}$'),
    created_at          timestamptz NOT NULL DEFAULT now(),
    processed_at        timestamptz,
    CHECK ((status = 'rejected') = (document_id IS NULL)),
    CHECK ((status = 'processing') = (processed_at IS NULL)),
    UNIQUE (id, case_id, firm_id),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE,
    -- The document must belong to the same case and firm (its kind is checked below).
    FOREIGN KEY (document_id, case_id, firm_id) REFERENCES documents (id, case_id, firm_id)
);

CREATE INDEX statement_uploads_case_idx ON statement_uploads (case_id, created_at);
CREATE INDEX statement_uploads_firm_idx ON statement_uploads (firm_id, created_at);

CREATE FUNCTION itr_statement_document_is_statement() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.document_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM documents WHERE id = NEW.document_id AND kind = 'bank_statement') THEN
        RAISE EXCEPTION 'statement document must be a bank statement of the same case';
    END IF;
    RETURN NEW;
END $$;

CREATE TRIGGER statement_uploads_document_kind BEFORE INSERT OR UPDATE OF document_id ON statement_uploads
    FOR EACH ROW EXECUTE FUNCTION itr_statement_document_is_statement();

-- The reviewed upload must be a stored statement of the same case and firm.
ALTER TABLE cases ADD FOREIGN KEY (reviewed_upload_id, id, firm_id)
    REFERENCES statement_uploads (id, case_id, firm_id);

CREATE FUNCTION itr_reviewed_upload_is_stored() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.reviewed_upload_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM statement_uploads WHERE id = NEW.reviewed_upload_id AND document_id IS NOT NULL) THEN
        RAISE EXCEPTION 'reviewed upload must be a stored statement of the same case';
    END IF;
    RETURN NEW;
END $$;

CREATE TRIGGER cases_reviewed_upload_stored BEFORE UPDATE OF reviewed_upload_id ON cases
    FOR EACH ROW EXECUTE FUNCTION itr_reviewed_upload_is_stored();

-- E-mail outbox -------------------------------------------------------------------
-- Every notification is recorded here. Secret-bearing bodies (one-time links)
-- are kept only until delivered or until the link expires.

CREATE TABLE email_outbox (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    idempotency_key     text NOT NULL UNIQUE CHECK (length(idempotency_key) > 0),
    firm_id             uuid REFERENCES firms (id),
    case_id             uuid,
    template            text NOT NULL CHECK (length(template) > 0),
    recipient           text NOT NULL CHECK (recipient LIKE '%_@_%'),
    subject             text NOT NULL CHECK (length(subject) > 0),
    body_text           text,
    sensitive           boolean NOT NULL DEFAULT false,
    body_expires_at     timestamptz,
    status              text NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending', 'simulated', 'sent', 'failed', 'dead', 'superseded')),
    attempts            integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    next_attempt_at     timestamptz,
    last_error          text,
    provider_message_id text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    sent_at             timestamptz,
    CHECK (case_id IS NULL OR firm_id IS NOT NULL),
    CHECK ((status IN ('sent', 'simulated')) = (sent_at IS NOT NULL)),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id)
);

CREATE INDEX email_outbox_due_idx ON email_outbox (status, next_attempt_at);

-- Development-only simulated inbox (local `npm run dev`; stays empty in production).
CREATE TABLE dev_mailbox (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    outbox_id  uuid NOT NULL UNIQUE REFERENCES email_outbox (id),
    recipient  text NOT NULL CHECK (recipient LIKE '%_@_%'),
    subject    text NOT NULL CHECK (length(subject) > 0),
    body_text  text NOT NULL,
    link       text,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL
);

CREATE INDEX dev_mailbox_expiry_idx ON dev_mailbox (expires_at);

-- Audit events --------------------------------------------------------------------
-- Append-only security history. details_json must not hold personal or financial data.

CREATE TABLE audit_events (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    firm_id      uuid REFERENCES firms (id),
    case_id      uuid,
    actor_kind   text NOT NULL CHECK (actor_kind IN ('ca', 'client', 'system', 'admin')),
    actor_id     text,
    action       text NOT NULL CHECK (length(action) > 0),
    details_json jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(details_json) = 'object'),
    ip_hash      text CHECK (ip_hash IS NULL OR ip_hash ~ '^[0-9a-f]{64}$'),
    created_at   timestamptz NOT NULL DEFAULT now(),
    CHECK (case_id IS NULL OR firm_id IS NOT NULL),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id)
);

CREATE INDEX audit_events_firm_idx ON audit_events (firm_id, created_at);
CREATE INDEX audit_events_case_idx ON audit_events (case_id, created_at);

CREATE TRIGGER audit_events_append_only BEFORE UPDATE OR DELETE ON audit_events
    FOR EACH ROW EXECUTE FUNCTION itr_reject_change();

-- Lock the tables away from Supabase's public Data API ---------------------------------

DO $$
DECLARE
    t text;
BEGIN
    FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = current_schema() LOOP
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
        EXECUTE 'REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated';
        EXECUTE 'REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM anon, authenticated';
    END IF;
END $$;

-- Private file storage bucket (Supabase only) -----------------------------------------

DO $$
BEGIN
    IF to_regclass('storage.buckets') IS NOT NULL THEN
        INSERT INTO storage.buckets (id, name, public) VALUES ('itr-private', 'itr-private', false)
        ON CONFLICT (id) DO NOTHING;
    END IF;
END $$;

INSERT INTO schema_migrations (version, name) VALUES (1, 'initial_schema');

COMMIT;
